import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

/**
 * LoginModal.jsx
 * --------------------------------------
 * A demo-friendly OTP-based login/register popup.
 * - Works with or without Twilio (demo mode)
 * - Expects backend endpoints:
 *     POST /api/auth/otp/request  -> { ok, demo, otp? }
 *     POST /api/auth/otp/verify   -> { ok, token, user }
 */

export default function LoginModal({ open, onClose, onLogin }) {
  const [step, setStep] = useState(0); // 0 = enter phone, 1 = enter OTP
  const [phone, setPhone] = useState("");
  const [name, setName] = useState("");
  const [otp, setOtp] = useState("");
  const [loading, setLoading] = useState(false);
  const [demoOtp, setDemoOtp] = useState(null);

  useEffect(() => {
    if (!open) {
      // Reset state whenever modal closes
      setStep(0);
      setPhone("");
      setName("");
      setOtp("");
      setDemoOtp(null);
      setLoading(false);
    }
  }, [open]);

  // --- Request OTP ---
  async function requestOtp() {
    if (!phone) return alert("Please enter your mobile number (e.g. +91...)");
    setLoading(true);
    try {
      const res = await fetch("/api/auth/otp/request", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone }),
      });
      const data = await res.json();
      setLoading(false);
      if (data.ok) {
        if (data.demo && data.otp) setDemoOtp(data.otp); // Demo mode: show OTP for testing
        setStep(1);
        setTimeout(() => document.getElementById("otpInput")?.focus(), 200);
      } else {
        alert(data.error || "Failed to send OTP");
      }
    } catch (err) {
      setLoading(false);
      console.error(err);
      alert("Network error while requesting OTP");
    }
  }

  // --- Verify OTP ---
  async function verifyOtp() {
    if (!otp) return alert("Enter the OTP you received");
    setLoading(true);
    try {
      const res = await fetch("/api/auth/otp/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone, otp, name }),
      });
      const data = await res.json();
      setLoading(false);
      if (data.ok) {
        onLogin(data); // { token, user }
        onClose();
      } else {
        alert(data.error || "Invalid OTP, please try again");
      }
    } catch (err) {
      setLoading(false);
      console.error(err);
      alert("Network error while verifying OTP");
    }
  }

  if (!open) return null;

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(15, 18, 25, 0.55)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 9999,
        padding: 16,
      }}
      onClick={onClose}
    >
      <motion.div
        onClick={(e) => e.stopPropagation()}
        initial={{ scale: 0.96, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 0.25 }}
        style={{
          width: 420,
          maxWidth: "95%",
          background: "white",
          borderRadius: 16,
          padding: 22,
          boxShadow: "0 25px 60px rgba(2, 6, 23, 0.35)",
        }}
      >
        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <h3 style={{ margin: 0 }}>Sign in / Register</h3>
          <button
            onClick={onClose}
            style={{
              background: "transparent",
              border: 0,
              fontSize: 22,
              lineHeight: 1,
              cursor: "pointer",
              color: "#6b7280",
            }}
            aria-label="Close"
          >
            ✕
          </button>
        </div>

        <div style={{ marginTop: 14 }} />

        {/* Step 0: Enter phone */}
        {step === 0 && (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <input
              placeholder="+91 98xxxxxxx"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              style={{
                padding: 12,
                borderRadius: 10,
                border: "1px solid #e6eaf5",
                fontSize: 15,
              }}
            />
            <input
              placeholder="Your name (optional)"
              value={name}
              onChange={(e) => setName(e.target.value)}
              style={{
                padding: 12,
                borderRadius: 10,
                border: "1px solid #e6eaf5",
                fontSize: 15,
              }}
            />

            <div style={{ display: "flex", gap: 10 }}>
              <button
                onClick={requestOtp}
                className="btn"
                style={{ flex: 1 }}
                disabled={loading}
              >
                {loading ? "Sending..." : "Send OTP"}
              </button>
              <button
                onClick={() => alert("Google Sign-in can be added via Firebase later.")}
                className="btn btn-outline"
                style={{ flex: 1 }}
              >
                Google
              </button>
            </div>

            <small style={{ color: "#6b7280" }}>
              For demo only — OTP will be shown in your terminal if Twilio is disabled.
            </small>

            {demoOtp && (
              <div
                style={{
                  marginTop: 6,
                  padding: 10,
                  borderRadius: 8,
                  background: "#f9fafb",
                  border: "1px dashed #cbd5e1",
                }}
              >
                Demo OTP: <strong>{demoOtp}</strong>
              </div>
            )}
          </div>
        )}

        {/* Step 1: Verify OTP */}
        {step === 1 && (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <input
              id="otpInput"
              placeholder="Enter 6-digit OTP"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              style={{
                padding: 12,
                borderRadius: 10,
                border: "1px solid #e6eaf5",
                fontSize: 15,
              }}
            />

            <div style={{ display: "flex", gap: 10 }}>
              <button
                onClick={verifyOtp}
                className="btn"
                style={{ flex: 1 }}
                disabled={loading}
              >
                {loading ? "Verifying..." : "Verify OTP"}
              </button>
              <button
                onClick={() => {
                  setStep(0);
                  setOtp("");
                  setDemoOtp(null);
                }}
                className="btn btn-outline"
                style={{ flex: 1 }}
              >
                Back
              </button>
            </div>

            <small style={{ color: "#6b7280" }}>
              Didn’t get it? Try again or check terminal for demo OTP.
            </small>
          </div>
        )}
      </motion.div>
    </div>
  );
}
